package com.autoops.workflow.entity;import jakarta.persistence.*;@Entity @Table(name="wait_until_steps")public class WaitUntilStep extends WorkflowStep{@Column(name="check_type",nullable=false)private String checkType;@Column(name="check_command",columnDefinition="text")private String checkCommand;@Column(name="expected_output")private String expectedOutput;@Column(name="check_interval_seconds",nullable=false)private Integer checkIntervalSeconds=5;@Column(name="timeout_seconds",nullable=false)private Integer timeoutSeconds=120;public String checkCommand(){return checkCommand;}public int intervalSeconds(){return checkIntervalSeconds;}public int timeoutSeconds(){return timeoutSeconds;}public boolean matches(int code,String out){return switch(checkType){case"EXIT_CODE"->code==0;case"OUTPUT_CONTAINS"->out!=null&&out.contains(expectedOutput);case"FILE_EXISTS","SERVICE_ACTIVE"->code==0;default->false;};}}
